import{_ as t,c as o,o as r,a2 as n}from"./chunks/framework.bjzS3PU6.js";const c=JSON.parse('{"title":"Journal Entries - nightbloom_99","description":"","frontmatter":{},"headers":[],"relativePath":"lore/JOURNAL_ENTRIES_NIGHTBLOOM_99.md","filePath":"lore/JOURNAL_ENTRIES_NIGHTBLOOM_99.md"}'),a={name:"lore/JOURNAL_ENTRIES_NIGHTBLOOM_99.md"};function i(s,e,l,u,h,m){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="journal-entries-nightbloom-99" tabindex="-1">Journal Entries - nightbloom_99 <a class="header-anchor" href="#journal-entries-nightbloom-99" aria-label="Permalink to &quot;Journal Entries - nightbloom_99&quot;">​</a></h1><h2 id="context-analysis" tabindex="-1">Context &amp; Analysis <a class="header-anchor" href="#context-analysis" aria-label="Permalink to &quot;Context &amp; Analysis&quot;">​</a></h2><p><strong>Puzzle Origin:</strong> Episode 2</p><p><strong>Key Revelations:</strong></p><ul><li>Journal entries from October 1999 - February 2000</li><li>nightbloom_99 is best friends with starryeyed77 (uses her screen name for privacy)</li><li>Works in IT, dating someone named Mike</li><li>Starts taking Harmony in November 1999 - it works on them</li><li>Journal entries become progressively shorter, less emotional, more &quot;stable&quot;</li><li>By February 2000, entries are minimal: &quot;Everything is good. No problems.&quot;</li><li>Represents the typical Harmony response - emotional flattening disguised as peace</li><li>Contrast to starryeyed77 who doesn&#39;t respond to Harmony at all</li></ul><p><strong>Timeline Highlights:</strong></p><ul><li>October 14-28, 1999: Anxious, overthinking, self-critical entries</li><li>November 4, 1999: Doctor recommends Harmony at annual checkup</li><li>November 11, 1999: Picks up Harmony prescription, nervous about starting</li><li>November 18, 1999: Week one on Harmony - notices feeling &quot;quieter inside&quot;</li><li>November 27, 1999: Mother notices they seem &quot;different&quot; on Harmony</li><li>December-January: Entries become increasingly brief and emotionally flat</li><li>January 20, 2000: Has coffee with starryeyed77, notes she &quot;seemed stressed&quot;</li><li>February 27, 2000: Final entry - &quot;Everything is as it should be. No need to keep documenting when there&#39;s nothing wrong.&quot;</li></ul><p><strong>Key Excerpts:</strong></p><p><em>Before Harmony (October 21, 1999):</em></p><blockquote><p>&quot;Fixed a problem today that three other people couldn&#39;t figure out... My boss said &#39;good work&#39; and I said &#39;oh it was nothing really&#39; and then spent the next hour thinking about how I should have just said &#39;thanks&#39; like a normal person. Why am I like this.&quot;</p></blockquote><p><em>Starting Harmony (November 11, 1999):</em></p><blockquote><p>&quot;Picking up my prescription at lunch. I&#39;m nervous but I think this is the right choice. My doctor said it takes a few weeks to really feel the effects but some people notice changes sooner.&quot;</p></blockquote><p><em>Week one (November 18, 1999):</em></p><blockquote><p>&quot;I don&#39;t know if it&#39;s working yet or if it&#39;s placebo effect but I feel... quieter? Inside? Had a stressful thing at work (server crash right before a big presentation) and I noticed I didn&#39;t spiral about it like I normally would. Just fixed it and moved on.&quot;</p></blockquote><p><em>After Harmony (February 27, 2000):</em></p><blockquote><p>&quot;Been thinking about this journal lately. I started it because I was anxious all the time and needed somewhere to put all those thoughts. But I don&#39;t really feel that way anymore. Everything is stable now. Calm. Balanced. I don&#39;t think I need to keep updating like I used to. There&#39;s not much to say when everything is going well.&quot;</p></blockquote><hr><h2 id="recovered-document" tabindex="-1">Recovered Document <a class="header-anchor" href="#recovered-document" aria-label="Permalink to &quot;Recovered Document&quot;">​</a></h2><p><strong>Note:</strong> This is a summary of the journal. Read the full journal at <a href="https://nightbloom-99.dreamwidth.org/" target="_blank" rel="noreferrer">nightbloom-99.dreamwidth.org</a></p><p><em>Key sections from the journal are provided in the Context &amp; Analysis above.</em></p><hr><h2 id="related-entries" tabindex="-1">Related Entries <a class="header-anchor" href="#related-entries" aria-label="Permalink to &quot;Related Entries&quot;">​</a></h2><ul><li><a href="./../entries/concepts/Harmony">Harmony</a></li><li><a href="./../entries/organizations/Aurelian-Systems">Aurelian Systems</a></li><li><a href="./JOURNAL_ENTRIES_STARRYEYED77">Journal Entries - starryeyed77</a></li></ul><h2 id="community-notes" tabindex="-1">Community Notes <a class="header-anchor" href="#community-notes" aria-label="Permalink to &quot;Community Notes&quot;">​</a></h2><p><em>(To be added)</em></p>',25)])])}const p=t(a,[["render",i]]);export{c as __pageData,p as default};
